def get_bid(day_context, my_status, opponents_status):
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    WATER_REQ = 9
    DAILY_SALARY = 90

    desperate = hp <= 2 or my_status['no_water_days'] >= 1

    # Get highest previous bid among opponents (yesterday)
    high_bid_yesterday = 0
    for opp_id, opp in opponents_status.items():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            if prev['bid'] > high_bid_yesterday:
                high_bid_yesterday = prev['bid']

    if desperate:
        # Need to win at all costs
        bid = min(budget, max(DAILY_SALARY * 1.2, high_bid_yesterday + 5))
    else:
        # Normal: evaluate supply scarcity
        supply_ratio = (supply - 15) / 10.0
        if supply_ratio < 0.3:
            base = DAILY_SALARY * 0.7
        elif supply_ratio < 0.7:
            base = DAILY_SALARY * 0.5
        else:
            base = DAILY_SALARY * 0.35
        # If yesterday's high bid was high and we have HP buffer, undercut
        if high_bid_yesterday > base and hp > 3:
            bid = max(DAILY_SALARY * 0.3, high_bid_yesterday * 0.9)
        else:
            bid = base

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents are alive, bid minimal to save money
    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    eric_is_alive = False
    eric_prev_bid = 0.0

    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])
            if opp_id == "Eric":
                eric_is_alive = True
                if prev and prev.get('bid') is not None:
                    eric_prev_bid = prev['bid']

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    current_day = day_context['day']
    current_supply = day_context['supply']

    # 1. Critical HP: Prioritize survival above all else
    if my_status['hp'] <= 3:
        bid_amount = DAILY_SALARY * 1.05 # Slightly more than salary
        if eric_is_alive and eric_prev_bid > DAILY_SALARY * 0.8:
            bid_amount = max(bid_amount, eric_prev_bid + 10.0) # Try to beat Eric if he was aggressive
        return min(my_status['budget'], bid_amount)

    # 2. End of game: Ensure survival in the final days
    if current_day >= EPISODE_DAYS - 2:
        bid_amount = DAILY_SALARY * 0.9 # High bid to ensure water
        if eric_is_alive and eric_prev_bid > DAILY_SALARY * 0.7:
            bid_amount = max(bid_amount, eric_prev_bid + 5.0)
        return min(my_status['budget'], bid_amount)

    # 3. Base bid logic, reacting to opponents and supply
    bid_amount = DAILY_SALARY * 0.6 # Moderate base bid

    if highest_prev_bid >= DAILY_SALARY * 0.8: # If opponents were bidding very high
        bid_amount = max(bid_amount, highest_prev_bid + 5.0) # Add a small buffer
    elif highest_prev_bid > 0: # If there were bids, but not extremely high
        bid_amount = max(bid_amount, highest_prev_bid + 2.0)

    # Adjust bid based on supply:
    # If supply is tight, increase bid
    if current_supply <= WATER_REQ + 5: # e.g., supply 15-18
        bid_amount = max(bid_amount, DAILY_SALARY * 0.7)
        if eric_is_alive and eric_prev_bid > 0:
            bid_amount = max(bid_amount, eric_prev_bid + 5.0) # Be more aggressive against Eric in tight supply
    # If supply is abundant, we can be less aggressive
    elif current_supply >= WATER_REQ * 2 - 5: # e.g., supply 21-25
        bid_amount = min(bid_amount, DAILY_SALARY * 0.5)

    # Ensure bid is at least a minimal amount if budget allows, otherwise 0
    final_bid = max(1.0, bid_amount) if my_status['budget'] > 0 else 0.0

    # Final check: bid cannot exceed budget
    return min(my_status['budget'], final_bid)

