def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday immediate pressure signals from previous_trace
    prev_bids = []
    prev_hp_after = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass
        try:
            prev_hp_after.append(float(prev.get('hp_after', 0.0)))
        except Exception:
            pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Base bid depends on supply: higher supply -> bid less aggressively
    # supply is in [15,25]. Normalize to [0,1]
    if MAX_SUPPLY <= MIN_SUPPLY:
        supply_norm = 0.5
    else:
        supply_norm = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
    supply_norm = max(0.0, min(1.0, supply_norm))

    # If someone previously overcommitted, we need to secure enough water.
    # Use thresholds relative to daily salary.
    aggressive_trigger = 0.75 * DAILY_SALARY
    moderate_trigger = 0.45 * DAILY_SALARY

    # If we are already in danger (low hp or multiple no-water days), ramp.
    danger = (my_hp <= 2.5) or (my_no_water_days >= 2)

    # Compute desired fraction of daily salary.
    if highest_prev_bid >= aggressive_trigger:
        # Cindy-like behavior: they can survive with high bids; we must compete but avoid full burn.
        if danger:
            frac = 0.85
        else:
            frac = 0.65
    elif highest_prev_bid >= moderate_trigger:
        if danger:
            frac = 0.75
        else:
            frac = 0.55
    else:
        # When others were low-bidding (Alex/Bob-like deaths), we can bid just enough.
        if danger:
            frac = 0.70
        else:
            # More supply -> lower bid
            frac = 0.45 - 0.15 * supply_norm

    # Convert to bid amount with budget cap.
    target_bid = frac * DAILY_SALARY

    # Additional small adjustment: if supply is low, competition is tighter.
    if supply <= float(MIN_SUPPLY) + 1.0:
        target_bid *= 1.10
    elif supply >= float(MAX_SUPPLY) - 1.0:
        target_bid *= 0.90

    # Ensure non-negative and not exceeding budget.
    bid = max(0.0, min(my_budget, target_bid))

    # Never bid more than a reasonable cap to preserve budget for later days.
    # (But still allow high bids if budget is large.)
    bid_cap = max(0.0, min(my_budget, DAILY_SALARY * 1.05))
    bid = min(bid, bid_cap)

    return float(bid)
